const rootId = $('Drive: Crear Unidad').first().json.id;
const names = ['0. COORD','1. SUPERVISION','2. FOOTAGE','3. RECURSOS','4. EDITABLES','5. FINALES'];
return names.map(name => ({ json: { name, parent: rootId } }));

const nombre = $('Webhook').first().json.body.nombre;
const l1 = $('Drive: Subcarpetas N1').all().map(i => i.json);
const idDe = (kw) => { const f = l1.find(x => (x.name || '').includes(kw)); return f ? f.id : null; };
const items = [];
const push = (parent, names) => { if (parent) names.forEach(name => items.push({ json: { name, parent } })); };
push(idDe('COORD'), ['00. PLANTILLAS-DOCUMENTOS','01. KIT DE POST']);
push(idDe('SUPERVISION'), ['00. OCF','01. PROXY','03. CC']);
push(idDe('FOOTAGE'), ['00. OCF','01. PROXY','03. CC']);
push(idDe('RECURSOS'), ['1. [3D]_' + nombre, '2. [GRÁFICAS]_' + nombre, '3. [VFX]_' + nombre, '4. [MOTION]_' + nombre, '5. [CONFORMADO]_' + nombre]);
return items;

const l2 = $('Drive: Subcarpetas N2').all().map(i => i.json);
const plantillas = l2.find(f => (f.name || '').includes('PLANTILLAS'));
if (plantillas) return [{ json: { coordId: plantillas.id } }];
const l1 = $('Drive: Subcarpetas N1').all().map(i => i.json);
const coord = l1.find(f => (f.name || '').includes('COORD'));
return [{ json: { coordId: coord.id } }];

const proj = $json.data || $json;
const rootFolderId = proj.root_folder_id || (proj.root_asset && proj.root_asset.id) || proj.root_asset_id;
const frameProjectId = proj.id;
return ['00. OFFLINE','01. POST','02. ONLINE','03. MASTERS'].map(name => ({ json: { name, rootFolderId, frameProjectId } }));

const body = $('Webhook').first().json.body;
/* cada bloque de automatizaciones puede venir apagado desde el hub (auto_drive /
   auto_frame / auto_discord). Si un nodo no se ejecutó, $('Nodo') tira error:
   por eso todas las lecturas pasan por estos accesores tolerantes. */
const one = (n) => { try { return $(n).first().json; } catch (e) { return null; } };
const many = (n) => { try { return $(n).all().map(i => i.json); } catch (e) { return []; } };

const root = one('Drive: Crear Unidad');
const l1 = many('Drive: Subcarpetas N1');
const find = (kw) => { const f = l1.find(x => (x.name || '').includes(kw)); return f ? f.id : ''; };
const desglose = one('Copia Desglose');
const brief = one('Copia Brief');
const feedback = one('Copia Feedback');
const notas = one('Crear Doc Notas');
const frame = one('Frame: carpetas');
const dsc = one('Discord: IDs') || {};
const folderUrl = (id) => id ? 'https://drive.google.com/drive/folders/' + id : '';
const docUrl = (kind, o) => (o && o.id) ? 'https://docs.google.com/' + kind + '/d/' + o.id : '';
const links = {
  driveRoot: folderUrl(root && root.id),
  coord: folderUrl(find('COORD')),
  supervision: folderUrl(find('SUPERVISION')),
  footage: folderUrl(find('FOOTAGE')),
  recursos: folderUrl(find('RECURSOS')),
  editables: folderUrl(find('EDITABLES')),
  finales: folderUrl(find('FINALES')),
  notas: docUrl('document', notas),
  desglose: docUrl('spreadsheets', desglose),
  brief: docUrl('presentation', brief),
  feedback: docUrl('presentation', feedback),
  frameio: (frame && frame.frameProjectId) ? 'https://next.frame.io/project/' + frame.frameProjectId : ''
};
Object.keys(links).forEach(k => { if (!links[k]) delete links[k]; });
/* Links pegados a mano en el armado, para lo que se eligió no crear automáticamente.
   Lo que sí se creó siempre gana: es lo que existe de verdad. */
const manual = (body && typeof body.links === 'object' && body.links) ? body.links : {};
Object.keys(manual).forEach(k => {
  const v = String(manual[k] == null ? '' : manual[k]).trim();
  /* solo URLs: si alguien manda cualquier cosa, no se guarda un link muerto */
  if (/^https?:\/\//i.test(v) && !links[k]) links[k] = v;
});
const id = 'p_' + Date.now();
const now = new Date().toISOString();
const year = String(new Date().getFullYear());
const row = {
  id,
  nombre: body.nombre,
  cliente: body.cliente || '',
  agencia: body.agencia || '',
  productora: body.productora || '',
  director: body.director || '',
  ep_nombre: body.ep_nombre || '', ep_email: body.ep_email || '',
  prod_nombre: body.prod_nombre || '', prod_email: body.prod_email || '',
  coord_nombre: body.coord_nombre || '', coord_email: body.coord_email || '',
  tareas_json: JSON.stringify(body.tareas || []),
  asignaciones_json: JSON.stringify(body.asignaciones || {}),
  status: 'por_activarse',
  year,
  links_json: JSON.stringify(links),
  created_at: now,
  taskDates_json: JSON.stringify(body.taskDates || {}),
  sintesis: body.sintesis || '',
  storyboard_url: body.storyboard_url || '',
  tratamiento_url: body.tratamiento_url || '',
  discord_category_id: dsc.discord_category_id ? "'" + dsc.discord_category_id : '',
  discord_avisos_id: dsc.discord_avisos_id ? "'" + dsc.discord_avisos_id : ''
