const project = { id, nombre: body.nombre, cliente: body.cliente || '', agencia: body.agencia || '', productora: body.productora || '', director: body.director || '', ep_nombre: body.ep_nombre || '', ep_email: body.ep_email || '', prod_nombre: body.prod_nombre || '', prod_email: body.prod_email || '', coord_nombre: body.coord_nombre || '', coord_email: body.coord_email || '', tareas: body.tareas || [], asignaciones: body.asignaciones || {}, status: 'por_activarse', year, links, calendario: [], taskDates: body.taskDates || {}, sintesis: body.sintesis || '', storyboard_url: body.storyboard_url || '' };
return [{ json: { row, project } }];

const body = $('Webhook').first().json.body;
/* El hub manda body.mails: un item por candidato con dirección, ya redactado
   (asunto + html) y con el flag `enviar`, que se apaga desde el armado. Lo que
   se ve en la vista previa del hub es exactamente esto.
   Si body.mails no llega (cliente viejo), se arma acá como antes: el template
   de abajo es el espejo de mailBuildHTML() en index.html — si tocás uno, tocá
   el otro. */
if (Array.isArray(body.mails)) {
  const salen = body.mails.filter(m => m && m.to && m.html && m.enviar !== false);
  return salen.map(m => ({ json: {
    to: String(m.to).trim(),
    subject: m.subject || ('Propuesta TEAM23 \u2014 ' + (body.nombre || '')),
    html: m.html
  } }));
}

const proyecto = body.nombre || '';
const cliente = body.cliente || '';
const sintesis = body.sintesis || '';
const storyboard = body.storyboard_url || '';

/* timeline real del proyecto: sale de taskDates (lo que se carga en el armado);
   body.timeline queda como fallback por compatibilidad */
let timeline = (body.timeline || []).filter(t => t && t.fase);
if (!timeline.length) {
  timeline = Object.entries(body.taskDates || {})
    .map(([fase, d]) => ({ fase: fase, inicio: (d || {}).inicio || '', fin: (d || {}).fin || '', notas: (d || {}).notas || '' }))
    .filter(t => t.inicio || t.fin || t.notas);
  timeline.sort((a, b) => String(a.inicio || '9999').localeCompare(String(b.inicio || '9999')));
}

const emails = [];
Object.entries(body.asignaciones || {}).forEach(([tarea, rows]) => {
  (rows || []).forEach(r => {
    if (r && r.email && r.estado === 'candidato') emails.push({ to: r.email, nombre: r.nombre || '', rol: tarea });
  });
});
if (!emails.length) return [{ json: { to: '', subject: 'sin candidatos', html: '' } }];

const fmt = d => /^\d{4}-\d{2}-\d{2}$/.test(d || '') ? d.split('-').reverse().join('/') : (d || 'a definir');
const conNotas = timeline.some(t => t.notas);
const th = txt => '<th style="text-align:left;padding:6px 10px;border-bottom:2px solid #0A0A0A;font-size:11px;letter-spacing:1px;">' + txt + '</th>';
const tlHtmlFor = rol => timeline.length
  ? '<table style="border-collapse:collapse;width:100%;font-size:14px;"><thead><tr>' + th('FASE') + th('INICIO') + th('FIN') + (conNotas ? th('NOTAS') : '') + '</tr></thead><tbody>' +
    timeline.map(t => {
      const mio = t.fase === rol;
      const td = 'padding:6px 10px;border-bottom:1px solid #ddd;' + (mio ? 'background:#FFF3F2;' : '');
      return '<tr>' +
        '<td style="' + td + (mio ? 'border-left:3px solid #FF2B1E;' : '') + '"><b>' + t.fase + '</b>' + (mio ? ' <span style="color:#FF2B1E;font-size:11px;font-weight:bold;">&larr; tu rol</span>' : '') + '</td>' +
        '<td style="' + td + '">' + fmt(t.inicio) + '</td>' +
        '<td style="' + td + '">' + fmt(t.fin) + '</td>' +
        (conNotas ? '<td style="' + td + 'font-size:12.5px;color:#555;">' + (t.notas || '') + '</td>' : '') +
      '</tr>';
    }).join('') + '</tbody></table>'
  : '<p style="color:#8A8A8A;">Timeline a definir.</p>';
const sb = storyboard ? '<p><b>Storyboard / referencias:</b> <a href="' + storyboard + '">' + storyboard + '</a></p>' : '';

return emails.map(e => ({ json: {
  to: e.to,
  subject: '\ud83c\udfac Propuesta TEAM23 \u2014 ' + proyecto + ' (' + e.rol + ')',
  html: '<div style="font-family:Helvetica,Arial,sans-serif;color:#0A0A0A;max-width:640px;">' +
    '<h2 style="margin:0 0 4px;font-size:22px;">' + proyecto + '</h2>' +
    '<p style="margin:0 0 16px;color:#FF2B1E;font-weight:bold;letter-spacing:2px;font-size:11px;">PROPUESTA DE PROYECTO \u00b7 TEAM23</p>' +
    '<p>Hola ' + (e.nombre || '') + ', te contactamos por un proyecto nuevo' + (cliente ? ' para <b>' + cliente + '</b>' : '') + '. Tu rol propuesto: <b>' + e.rol + '</b>.</p>' +
    (sintesis ? '<p style="margin:14px 0 6px;font-weight:bold;font-size:12px;letter-spacing:1px;">DE QU\u00c9 SE TRATA</p><p style="white-space:pre-line;">' + sintesis + '</p>' : '') + sb +
    '<p style="margin:14px 0 6px;font-weight:bold;font-size:12px;letter-spacing:1px;">TIMELINE TENTATIVO</p>' + tlHtmlFor(e.rol) +
