const sufijos = ['prod', 'coord', 'general'];
tareas.forEach(t => { const s = MAPA[t]; if (s && !sufijos.includes(s)) sufijos.push(s); });
return sufijos.map(s => ({ json: { name: slug + '-' + s, parent_id: String(cat.id) } }));

