let links = {}; try { links = JSON.parse(r.links_json || '{}'); } catch (e) {}
const lineas = ['\ud83d\ude80 **' + (r.nombre || 'Proyecto') + '** entr\u00f3 a pre-producci\u00f3n'];
const meta = [];
if (r.cliente) meta.push('Cliente: ' + r.cliente);
if (r.agencia) meta.push('Agencia: ' + r.agencia);
if (meta.length) lineas.push(meta.join(' \u00b7 '));
if (links.driveRoot) lineas.push('Drive: <' + links.driveRoot + '>');
if (links.frameio) lineas.push('Frame.io: <' + links.frameio + '>');
return [{ json: { channelId: ids.discord_avisos_id, content: lineas.join('\n') } }];

const cfg = $('CONFIG').first().json;
const guild = String(cfg.discordGuildId || '').trim();
const bot = $('Discord: Qui\u00e9n soy').first().json;
const VIEW = '1024';           /* VIEW_CHANNEL */
const VIEW_SEND = '3072';      /* VIEW_CHANNEL + SEND_MESSAGES */
const parseIds = v => String(v || '').split(',').map(s => s.trim()).filter(s => /^\d{5,}$/.test(s));
const users = parseIds(cfg.discordViewerUserIds);
const roles = parseIds(cfg.discordViewerRoleIds);
const overwrites = [
  { id: guild, type: 0, deny: VIEW },                 /* @everyone: no ve la categoria ni los canales */
  { id: String(bot.id), type: 1, allow: VIEW_SEND }   /* el bot se garantiza ver y escribir */
];
roles.forEach(id => overwrites.push({ id, type: 0, allow: VIEW }));
users.forEach(id => overwrites.push({ id, type: 1, allow: VIEW }));
return [{ json: { overwrites } }];

